// No external communications are sent by this guard.
const { campaignRecordId, submittedAt: capturedSubmittedAt } = input.config();
const campaigns = base.getTable("tblAVAA6uBPaMj28P");
const STATE = "fldD8UHFW69VTr1y6";
const SUBMITTED = "fldTwdx8HHei9LeQp";
const STAGE = "fldOVJmlGWxW1dveo";
const EXCEPTION = "fld1vE0Exqlw7MMvq";
const normalize = (value) => {
  if (!value) return "";
  const time = Date.parse(String(value));
  return Number.isFinite(time) ? new Date(time).toISOString() : "";
};
const readLedger = (raw) => {
  if (!raw) return { version: 1, attempts: {} };
  let ledger;
  try { ledger = JSON.parse(raw); } catch { throw new Error("Notification audit is invalid JSON. Check it before sending any client notices."); }
  if (ledger.version !== 1 || !ledger.attempts || typeof ledger.attempts !== "object" || Array.isArray(ledger.attempts)) {
    throw new Error("Notification audit has an unsupported format. Check it before sending any client notices.");
  }
  return ledger;
};
output.set("shouldSend", false);
output.set("submissionKey", "");
output.set("claimToken", "");
const run = async () => {
  const record = await campaigns.selectRecordAsync(campaignRecordId);
  if (!record) return;
  const submittedAt = normalize(capturedSubmittedAt);
  if (!submittedAt || submittedAt !== normalize(record.getCellValue(SUBMITTED))) return;
  if (record.getCellValue(STAGE)?.name !== "Client Review" || record.getCellValue(EXCEPTION)) return;
  const key = campaignRecordId + ":" + submittedAt;
  const ledger = readLedger(record.getCellValueAsString(STATE));
  const prior = ledger.attempts[key];
  if (prior?.phase === "completed") {
    console.log("Skipped duplicate completed submission: " + key);
    return;
  }
  if (prior) {
    throw new Error("This submission already has a notification attempt (" + prior.phase + "). Check run history and Slack/email delivery before retrying; no duplicate will be sent automatically.");
  }
  const claimToken = Date.now().toString(36) + "-" + Math.random().toString(36).slice(2);
  ledger.attempts[key] = { submittedAt, phase: "claimed", claimToken, claimedAt: new Date().toISOString() };
  await campaigns.updateRecordAsync(campaignRecordId, { [STATE]: JSON.stringify(ledger) });
  const confirmed = await campaigns.selectRecordAsync(campaignRecordId);
  const confirmedLedger = readLedger(confirmed?.getCellValueAsString(STATE));
  if (confirmedLedger.attempts[key]?.claimToken !== claimToken) {
    throw new Error("Notification claim changed before sending. Check concurrent runs.");
  }
  if (normalize(confirmed.getCellValue(SUBMITTED)) !== submittedAt || confirmed.getCellValue(STAGE)?.name !== "Client Review" || confirmed.getCellValue(EXCEPTION)) {
    throw new Error("Submission changed after notification was claimed. No client notice was sent by this run.");
  }
  output.set("submissionKey", key);
  output.set("claimToken", claimToken);
  output.set("shouldSend", true);
};
await run();

