// Records successful action completion, not end-recipient delivery.
const { campaignRecordId, submissionKey, claimToken, channel } = input.config();
const campaigns = base.getTable("tblAVAA6uBPaMj28P");
const STATE = "fldD8UHFW69VTr1y6";
const record = await campaigns.selectRecordAsync(campaignRecordId);
if (!record) throw new Error("Campaign no longer exists; notification receipt could not be saved.");
let ledger;
try { ledger = JSON.parse(record.getCellValueAsString(STATE)); } catch { throw new Error("Notification audit cannot be read. Do not repeat a possibly completed send."); }
const attempt = ledger.attempts?.[submissionKey];
if (!attempt || attempt.claimToken !== claimToken) throw new Error("Notification claim changed. Check run history before any retry.");
if (channel === "slack") {
  attempt.slackSentAt = new Date().toISOString();
  attempt.phase = "slack_sent";
} else if (channel === "email") {
  attempt.emailSentAt = new Date().toISOString();
  attempt.phase = "completed";
} else {
  throw new Error("Unknown notification receipt channel.");
}
await campaigns.updateRecordAsync(campaignRecordId, { [STATE]: JSON.stringify(ledger) });
if (channel === "slack") {
  const current = await campaigns.selectRecordAsync(campaignRecordId);
  const currentTime = Date.parse(String(current?.getCellValue("fldTwdx8HHei9LeQp") || ""));
  if (currentTime !== Date.parse(attempt.submittedAt) || current?.getCellValue("fldOVJmlGWxW1dveo")?.name !== "Client Review" || current?.getCellValue("fld1vE0Exqlw7MMvq")) {
    throw new Error("Submission changed after Slack completed. Email was not sent. Review the recorded Slack result before retrying.");
  }
}

const { campaignRecordId } = input.config();

const campaigns = base.getTable("Campaigns");
const leadLists = base.getTable("Lead Lists");
const campaign = await campaigns.selectRecordAsync(campaignRecordId);

let summary = "## Target Audience Breakdown\n\nLead-list targeting details are not yet linked.";

const parseJson = (text) => {
  try { return JSON.parse(text || "{}"); } catch { return {}; }
};

const arrayText = (value) =>
  Array.isArray(value) ? value.filter(Boolean).join(", ") : "";

const labelize = (value) =>
  String(value || "")
    .toLowerCase()
    .split("_")
    .map((part) => part ? part[0].toUpperCase() + part.slice(1) : "")
    .join(" ");

const money = (value) => {
  const number = Number(value);
  if (!Number.isFinite(number)) return String(value || "");
  if (number >= 1000000000) return "$" + (number / 1000000000) + "B";
  if (number >= 1000000) return "$" + (number / 1000000) + "M";
  if (number >= 1000) return "$" + (number / 1000) + "K";
  return "$" + number;
};

const formatRange = (raw, type) => {
  const parts = String(raw || "").split(",").map((v) => Number(v.trim()));
  if (parts.length !== 2 || parts.some((v) => !Number.isFinite(v))) {
    return raw || "Not specified";
  }
  const [min, max] = parts;
  if (type === "employees") {
    const maxText = max >= 10001 ? "10,000+" : max.toLocaleString("en-US");
    return min.toLocaleString("en-US") + "–" + maxText + " employees";
  }
  return money(min) + "–" + money(max);
};

if (campaign) {
  const linkedLists = campaign.getCellValue("Lead List") || [];
  if (linkedLists.length) {
    const leadList = await leadLists.selectRecordAsync(linkedLists[0].id);

    const fieldText = (name) => {
      try { return (leadList.getCellValueAsString(name) || "").trim(); }
      catch { return ""; }
    };

    const companyFilters = parseJson(fieldText("DiscoLike Company Filters JSON"));
    const contactFilters = parseJson(fieldText("Contact Filters JSON"));

    const industries =
      arrayText(companyFilters.category?.map(labelize)) ||
      fieldText("Industry Filters") ||
      fieldText("Included Industries") ||
      "Not specified";

    const companyGeography =
      arrayText(companyFilters.country) ||
      fieldText("Country Filters") ||
      fieldText("Included Countries") ||
      "Worldwide";

    const contactGeography =
      [arrayText(contactFilters.person_country), arrayText(contactFilters.person_state)]
        .filter(Boolean)
        .join(" — ") ||
      "No separate contact-location restriction";

    const companySize = formatRange(fieldText("Employee Range"), "employees");
    const revenue = formatRange(companyFilters.revenue_range, "revenue");
    const technology = arrayText(companyFilters.tech_stack) || "Not specified";

    const personaText = fieldText("Target Personas");
    const titles =
      (personaText.split(/\.\s+(?:Prioritize|Do not|Exclude)/i)[0] || "").trim() ||
      arrayText(contactFilters.titles) ||
      arrayText(contactFilters.job_titles) ||
      "Not specified";

    summary = [
      "## Target Audience Breakdown",
      "",
      `• **Target Industries:** ${industries}`,
      `• **Company Geography:** ${companyGeography}`,
      `• **Contact Geography:** ${contactGeography}`,
      `• **Company Size:** ${companySize}`,
      `• **Revenue Range:** ${revenue}`,
      `• **Technology:** ${technology}`,
      `• **Target Titles:** ${titles}`,
    ].join("\n");
  }
}

output.set("targetAudienceBreakdown", summary);

// Read-only check immediately before the existing email action.
