try { ledger = JSON.parse(record.getCellValueAsString("fldD8UHFW69VTr1y6")); } catch { throw new Error("Notification audit cannot be read. Email was not sent."); }
const attempt = ledger.attempts?.[submissionKey];
if (!attempt || attempt.claimToken !== claimToken || attempt.phase !== "slack_sent") throw new Error("Notification claim is not ready for email. Check run history before retrying.");
const currentTime = Date.parse(String(record.getCellValue("fldTwdx8HHei9LeQp") || ""));
if (currentTime !== Date.parse(attempt.submittedAt) || record.getCellValue("fldOVJmlGWxW1dveo")?.name !== "Client Review" || record.getCellValue("fld1vE0Exqlw7MMvq")) {
  throw new Error("Submission changed before email. Email was not sent; do not replay Slack.");
}

